const ALIAS_MAP: Record<string, string> = {
  'bubble-pop': 'interactive',
  'concentric-rings': 'counter-ring',
  'dual-ring-reverse': 'counter-ring',
  'progress': 'progress-bar',
  'linear-progress': 'progress-bar',
  'circular-progress': 'progress-ring',
  'ring-progress': 'progress-ring',
  'steps': 'progress-steps',
  'stepped-progress': 'progress-steps',
  'fidget': 'fidget-spinner',
  'spin-fidget': 'fidget-spinner',
};

export function getLoaderStyles(type: string): string | undefined {
  const resolved = ALIAS_MAP[type] || type;
  return LOADER_STYLES[resolved];
}
